import { test, expect } from '@playwright/test';

test.describe('Onboarding Tour Modal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display onboarding modal on page load', async ({ page }) => {
    const modal = page.getByRole('dialog', { name: /onboarding/i });
    await expect(modal).toBeVisible();
  });

  test('should advance to next step when clicking next button', async ({ page }) => {
    const modal = page.getByRole('dialog', { name: /onboarding/i });
    await expect(modal).toBeVisible();

    const stepOneTitle = page.getByText(/step 1/i);
    await expect(stepOneTitle).toBeVisible();

    const nextButton = page.getByRole('button', { name: /next/i });
    await nextButton.click();

    const stepTwoTitle = page.getByText(/step 2/i);
    await expect(stepTwoTitle).toBeVisible();
  });

  test('should advance through all steps sequentially', async ({ page }) => {
    const modal = page.getByRole('dialog', { name: /onboarding/i });
    await expect(modal).toBeVisible();

    const nextButton = page.getByRole('button', { name: /next/i });

    // Step 1
    await expect(page.getByText(/step 1/i)).toBeVisible();
    await nextButton.click();

    // Step 2
    await expect(page.getByText(/step 2/i)).toBeVisible();
    await nextButton.click();

    // Step 3
    await expect(page.getByText(/step 3/i)).toBeVisible();
  });

  test('should go back to previous step when clicking back button', async ({ page }) => {
    const modal = page.getByRole('dialog', { name: /onboarding/i });
    await expect(modal).toBeVisible();

    const nextButton = page.getByRole('button', { name: /next/i });
    await nextButton.click();

    await expect(page.getByText(/step 2/i)).toBeVisible();

    const backButton = page.getByRole('button', { name: /back/i });
    await backButton.click();

    await expect(page.getByText(/step 1/i)).toBeVisible();
  });

  test('should close modal when clicking skip button', async ({ page }) => {
    const modal = page.getByRole('dialog', { name: /onboarding/i });
    await expect(modal).toBeVisible();

    const skipButton = page.getByRole('button', { name: /skip/i });
    await skipButton.click();

    await expect(modal).not.toBeVisible();
  });

  test('should show finish button on last step', async ({ page }) => {
    const nextButton = page.getByRole('button', { name: /next/i });

    // Navigate to last step
    await nextButton.click();
    await nextButton.click();

    const finishButton = page.getByRole('button', { name: /finish/i });
    await expect(finishButton).toBeVisible();
  });

  test('should close modal when clicking finish button on last step', async ({ page }) => {
    const modal = page.getByRole('dialog', { name: /onboarding/i });
    const nextButton = page.getByRole('button', { name: /next/i });

    // Navigate to last step
    await nextButton.click();
    await nextButton.click();

    const finishButton = page.getByRole('button', { name: /finish/i });
    await finishButton.click();

    await expect(modal).not.toBeVisible();
  });
});
